class Solution:
    def characterReplacement(self, s, k):
        count = [0] * 26
        left = maxf = 0
        for right, ch in enumerate(s):
            c = ord(ch) - 65
            count[c] += 1
            if count[c] > maxf:
                maxf = count[c]
            if right - left + 1 - maxf > k:
                count[ord(s[left]) - 65] -= 1
                left += 1
        return len(s) - left

