permutation-in-string.solution:
class Solution:
    def checkInclusion(self, s1, s2):
        m, n = len(s1), len(s2)
        if m > n:
            return False
        need = [0] * 26
        win = [0] * 26
        for ch in s1:
            need[ord(ch) - 97] += 1
        for ch in s2[:m]:
            win[ord(ch) - 97] += 1
        matches = sum(1 for i in range(26) if need[i] == win[i])
        for r in range(m, n):
            if matches == 26:
                return True
            i = ord(s2[r]) - 97
            win[i] += 1
            if win[i] == need[i]:
                matches += 1
            elif win[i] == need[i] + 1:
                matches -= 1
            j = ord(s2[r - m]) - 97
            win[j] -= 1
            if win[j] == need[j]:
                matches += 1
            elif win[j] == need[j] - 1:
                matches -= 1
        return matches == 26

