    def minSubArrayLen(self, target, nums):
        best = len(nums) + 1
        total = left = 0
        for right, x in enumerate(nums):
            total += x
            while total >= target:
                if right - left + 1 < best:
                    best = right - left + 1
                total -= nums[left]
                left += 1
        return 0 if best > len(nums) else best

