    def totalFruit(self, fruits):
        count = {}
        left = best = 0
        for right, f in enumerate(fruits):
            count[f] = count.get(f, 0) + 1
            while len(count) > 2:
                g = fruits[left]
                count[g] -= 1
                if count[g] == 0:
                    del count[g]
                left += 1
            if right - left + 1 > best:
                best = right - left + 1
        return best

