class MinStack:
    def __init__(self):
        self.st = []      # pairs (value, min of stack up to here)

    def push(self, val):
        m = val if not self.st or val < self.st[-1][1] else self.st[-1][1]
        self.st.append((val, m))

    def pop(self):
        self.st.pop()

    def top(self):
        return self.st[-1][0]

    def getMin(self):
        return self.st[-1][1]

