class Solution:
    def calculate(self, s):
        st = []
        num = 0
        op = "+"
        n = len(s)
        for i, ch in enumerate(s):
            if ch.isdigit():
                num = num * 10 + (ord(ch) - 48)
            if (not ch.isdigit() and ch != " ") or i == n - 1:
                if op == "+":
                    st.append(num)
                elif op == "-":
                    st.append(-num)
                elif op == "*":
                    st.append(st.pop() * num)
                else:
                    t = st.pop()
                    st.append(-(-t // num) if t < 0 else t // num)
                op = ch
                num = 0
        return sum(st)

