class Solution:
    def splitArray(self, nums, k):
        def pieces(limit):
            cnt, s = 1, 0
            for x in nums:
                if s + x > limit:
                    cnt += 1
                    s = 0
                s += x
            return cnt
        lo, hi = max(nums), sum(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if pieces(mid) <= k:
                hi = mid
            else:
                lo = mid + 1
        return lo

