    def mySqrt(self, x):
        lo, hi = 0, x
        while lo < hi:
            mid = (lo + hi + 1) // 2      # upper mid: we search the LAST k with k*k <= x
            if mid * mid <= x:
                lo = mid
            else:
                hi = mid - 1
        return lo
